import { Auction } from '@/types';
import AuctionCard from '@/components/AuctionCard';

async function getAuctions(): Promise<Auction[]> {
  try {
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/auctions`, {
      cache: 'no-store',
    });
    if (!res.ok) return [];
    return res.json();
  } catch {
    return [];
  }
}

export default async function HomePage() {
  const auctions = await getAuctions();

  return (
    <div>
      <h1 className="text-3xl font-bold text-gray-900 mb-8">Enchères en cours</h1>

      {auctions.length === 0 ? (
        <p className="text-gray-500 text-center py-20">
          Aucune enchère pour le moment. Créez la première !
        </p>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {auctions.map(auction => (
            <AuctionCard key={auction.id} auction={auction} />
          ))}
        </div>
      )}
    </div>
  );
}
